"""Render a loaded config to the `.sops.yaml` sops reads."""

from __future__ import annotations

import io

from ruamel.yaml import YAML
from ruamel.yaml.comments import CommentedMap, CommentedSeq
from ruamel.yaml.scalarstring import SingleQuotedScalarString

from .config import Config

HEADER = (
    "# GENERATED by sops-compose from sops/. Do not edit.\n"
    "# Edit the files under sops/ and run `sops-compose render`.\n"
)


def render(cfg: Config) -> str:
    """Deterministic: the same sources always render to the same bytes, which
    is what `check` relies on to detect a stale or hand-edited file."""
    rules = CommentedSeq()
    for rule in cfg.rules:
        entry = CommentedMap()
        entry["path_regex"] = SingleQuotedScalarString(rule.path_regex)
        age = CommentedSeq(cfg.keys[n] for n in rule.names)
        # Explicit column: ruamel's default spacing differs for the first item.
        column = 8 + max(len(cfg.keys[n]) for n in rule.names) + 1
        for i, name in enumerate(rule.names):
            age.yaml_add_eol_comment(f"# {name}", i, column=column)
        entry["age"] = age
        for k, v in rule.extra.items():
            entry[k] = v
        rules.append(entry)

    y = YAML()
    y.width = 4096
    y.indent(mapping=2, sequence=4, offset=2)
    buf = io.StringIO()
    y.dump({"creation_rules": rules}, buf)
    return HEADER + buf.getvalue()
